def gcd(a, b):
    if a == float('-inf'):
        if b == float('-inf'):
            raise ValueError("gcd() is greater than float('inf')")
        return 1 << (abs(b).bit_length() - 1)
    if b == float('-inf'):
        return 1 << (abs(a).bit_length() - 1)
    a = abs(a)
    b = abs(b)
    if a == 0:
        return b
    if b == 0:
        return a
    factors_of_two_in_a = a.bit_length() - 1
    factors_of_two_in_b = b.bit_length() - 1
    common_factors_of_two = min(factors_of_two_in_a, factors_of_two_in_b)
    a >>= factors_of_two_in_a
    b >>= factors_of_two_in_b
    while a != b:
        if a > b:
            a = a - b
            a >>= a.bit_length() - 1
        else:
            b = b - a
            b >>= b.bit_length() - 1
    return a << common_factors_of_two

