        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = Node()

    def insert(self, data):
        new_node = Node(data)
        cur = self.head
        while cur.next != None:
            cur = cur.next
        cur.next = new_node

    def delete(self):
        cur = self.head
        if cur.next == None:
            return None
        deleted_node = cur.next
        cur.next = deleted_node.next
        return deleted_node.data

    def print_list(self):
        cur = self.head.next
        while cur != None:
            print(cur.data)
            cur = cur.next

    def isEmpty(self):
        return self.head.next == None

