def unsigned_multiply_overflows(a: int, b: int) -> bool:
    if a == 0 or b == 0:
        return False
    a_half = a >> 1
    b_half = b >> 1
    a_last_bit = a & 1
    b_last_bit = b & 1
    if a_last_bit == 0:
        return (2**64 - 1) / b < a_half
    elif b_last_bit == 0:
        return (2**64 - 1) / a < b_half
    else:
        return ((2**64 - 1) - b_half) / b < a_half

