class MyStreamTokenizer:
    def __init__(self, text):
        self.text = text
        self.index = 0

        self.advance()

    def advance(self):
        self.token_type = self.text[self.index]
        self.string_value = self.token_type
        self.index += 1

def parse(tokenizer):
    base_name = tokenizer.string_value
    tokenizer.advance()
    params = []

    if tokenizer.token_type == "<":
        while True:
            tokenizer.advance()
            params.append(parse(tokenizer))
            if tokenizer.token_type != ',':
                break

        tokenizer.advance()

    return GenericType(base_name, params)

