        return None
    max = first
    max2 = first.next
    if max.key < max2.key:
        max, max2 = max2, max
    node = max2.next
    while node is not None:
        if node.key > max.key:
            max, max2 = node, max
        elif max2.key < node.key < max.key:
            max2 = node
        node = node.next
    return max2.key

