def compute_height(parent):
    n = len(parent)
    maxHeight = 0
    heights = [0] * n

    for vertex in range(n):
        if heights[vertex] != 0:
            continue
        height = 0
        i = vertex
        while i != -1:
            if heights[i] != 0:
                height += heights[i]
                break
            height += 1
            i = parent[i]

        maxHeight = max(maxHeight, height)
        i = vertex
        while i != -1:
            if heights[i] != 0:
                break
            heights[i] = height
            height -= 1

    return maxHeight

