def decrypt(s):
    crypt = []
    groups = s.split('#')
    for i, group in enumerate(groups):
        j = len(group) if (i == len(groups) - 1 and not s.endswith('#')) else (len(group) - 2 if len(group) > 2 else 0)

        for k in range(j):
            crypt.append(int(group[k:k+1]))
        if j < len(group):
            crypt.append(int(group[j:]))
    result = ""
    for c in crypt:
        result += chr(ord('a') + c - 1)
    return result

