    s1, s2 = s1.lower(), s2.lower()
    for i in range(len(s1)):
        seen[ord(s1[i])] += 1
    for i in range(len(s2)):
        if seen[ord(s2[i])] == 0: return False
        seen[ord(s2[i])] -= 1
    return all(x==0 for x in seen)

