class Connection:
    def __init__(self, dstAddr, dstPort, protocol, srcAddr, srcPort):
        self.dstAddr = dstAddr
        self.dstPort = dstPort
        self.protocol = protocol
        self.srcAddr = srcAddr
        self.srcPort = srcPort

    def __eq__(self, obj):
        if self is obj:
            return True
        if obj is None or type(obj) != type(self):
            return False
        if self.dstAddr != obj.dstAddr or self.dstPort != obj.dstPort or self.protocol != obj.protocol or self.srcAddr != obj.srcAddr or self.srcPort != obj.srcPort:
            return False
        return True

