    result = np.zeros(n, dtype=int)
    if total == 0:
        return result
    while(True):
        r = [np.random.randint(0, 2**256) for _ in range(n)]
        sum = np.sum(r)
        if sum == 0:
            continue
        for i in range(n):
            result[i] = (r[i] % total) + 1
        return result

