            return 'None'
        if id(obj) in self.visited:
            return '...'
        self.visited.add(id(obj))
        cl = type(obj)
        if cl == str:
            return obj
        if cl == list or cl == tuple:
            r = cl.__name__ + '[]{'
            for index, val in enumerate(obj):
                if index > 0:
                    r += ','
                if type(val).__name__ in ['int', 'float', 'bool', 'str', 'bytes']:
                    r += str(val)
                else:
                    r += self.to_string(val)
            return r + '}'
        r = cl.__name__
        r += '['
        for attr, val in obj.__dict__.items():
            if not r.endswith('['):
                r += ','
            r += attr + '='
            try:
                if type(val).__name__ in ['int', 'float', 'bool', 'str', 'bytes']:
                    r += str(val)
                else:
                    r += self.to_string(val)
