    s1 = [0] * (len(A) - 1)
    s1[0] = A[0]
    for i in range(1, len(A) - 1):
        s1[i] = s1[i - 1] + A[i]
    s2 = [0] * (len(A) - 1)
    s2[len(A) - 2] = A[len(A) - 1]
    for i in range(len(A) - 3, -1, -1):
        s2[i] = s2[i + 1] + A[i + 1]
    finalSum = float('inf')
    for j in range(len(s1)):
        sum = abs(s1[j] - s2[j])
        if sum < finalSum: finalSum = sum
    return finalSum

