def solution(S, P, Q):
    answer = [0]*len(P)
    chars = list(S)
    cumulativeAnswers = [[0]*(len(chars)+1) for _ in range(4)]
    for i in range(len(chars)):
        if i > 0:
            for j in range(4):
                cumulativeAnswers[j][i+1] = cumulativeAnswers[j][i]
        if chars[i] == 'A':
            cumulativeAnswers[0][i+1] += 1
        elif chars[i] == 'C':
            cumulativeAnswers[1][i+1] += 1
        elif chars[i] == 'G':
            cumulativeAnswers[2][i+1] += 1
        elif chars[i] == 'T':
            cumulativeAnswers[3][i+1] += 1
    for i in range(len(P)):
        for j in range(4):
            if (cumulativeAnswers[j][Q[i] + 1] - cumulativeAnswers[j][P[i]]) > 0:
                answer[i] = j + 1
                break
    return answer

