using System;

public class Program {
    public static int gcd(int a, int b) {
        if (a == int.MinValue) {
            if (b == int.MinValue) throw new ArgumentException("gcd() is greater than int.MaxValue");
            return 1 << Convert.ToString(Math.Abs(b), 2).Length - 1;
        }
        if (b == int.MinValue) return 1 << Convert.ToString(Math.Abs(a), 2).Length - 1;
        a = Math.Abs(a);
        b = Math.Abs(b);
        if (a == 0) return b;
        if (b == 0) return a;
        int factorsOf2InA = Convert.ToString(a, 2).Length - 1;
        int factorsOf2InB = Convert.ToString(b, 2).Length - 1;
        int commonFactorsOfTwo = Math.Min(factorsOf2InA, factorsOf2InB);
        a >>= factorsOf2InA;
        b >>= factorsOf2InB;
        while (a != b) {
            if (a > b) {
                a -= b;
                a >>= Convert.ToString(a, 2).Length - 1;
            } else {
                b -= a;
                b >>= Convert.ToString(b, 2).Length - 1;
            }
        }
        return a << commonFactorsOfTwo;
    }
}

