using System;
using System.IO;

class Program
{
    const int TEMP_DIR_ATTEMPTS = 10000;

    public static DirectoryInfo CreateTempDir() {
        string baseDir = Path.GetTempPath();
        string baseName = DateTime.Now.Ticks.ToString() + "-";
        for (int counter = 0; counter < TEMP_DIR_ATTEMPTS; counter ++) {
            DirectoryInfo tempDir = new DirectoryInfo(Path.Combine(baseDir, baseName + counter.ToString()));
            if (!tempDir.Exists) {
                tempDir.Create();
                return tempDir;
            }
        }
        throw new InvalidOperationException("Failed to create directory within " + TEMP_DIR_ATTEMPTS + " attempts (tried " + baseName + "0 to " + baseName + (TEMP_DIR_ATTEMPTS - 1) + ')');
    }
}

