codeA:
static boolean unsignedMultiplyOverflows (final long a, final long b) {
    if (a == 0 || b == 0) {
        return false;
    }
    final long aHalf = a>>> 1;
    final long bHalf = b>>> 1;
    final byte aLastBit = (byte) (a & 1);
    final byte bLastBit = (byte) (b & 1);
    if (aLastBit == 0) {
        return Long.MAX_VALUE / b < aHalf;
    } else if (bLastBit == 0) {
        return Long.MAX_VALUE / a < bHalf;
    } else {
        return (Long.MAX_VALUE - bHalf) / b < aHalf;
    }
}

codeB:
public static bool UnsignedMultiplyOverflows(ulong a, ulong b) {
    if (a == 0 || b == 0) {
        return false;
    }
    ulong aHalf = a >> 1;
    ulong bHalf = b >> 1;
    byte aLastBit = (byte) (a & 1);
    byte bLastBit = (byte) (b & 1);
    if (aLastBit == 0) {
        return ulong.MaxValue / b < aHalf;
    } else if (bLastBit == 0) {
        return ulong.MaxValue / a < bHalf;
    } else {
        return (ulong.MaxValue - bHalf) / b < aHalf;
    }
}

