public class GenericType {
    public string BaseName { get; set; }
    public List<GenericType> Params { get; set; }
    public GenericType(string baseName, List<GenericType> params) {
        BaseName = baseName;
        Params = params;
    }
}

public class MyStreamTokenizer
{
    private string _text;
    private int _index;
    public int TokenType { get; private set; }
    public string StringValue { get; private set; }

    public MyStreamTokenizer(string text)
    {
        _text = text;
        _index = 0;
        Advance();
    }

    public void Advance()
    {
        TokenType = _text[_index];
        StringValue = TokenType.ToString();
        _index++;
    }
}

public static GenericType Parse(MyStreamTokenizer tokenizer)
{
    var baseName = tokenizer.StringValue;
    tokenizer.Advance();
    var parameters = new List<GenericType>();

    if (tokenizer.TokenType == '<')
    {
        do {
            tokenizer.Advance();
            parameters.Add(Parse(tokenizer));
        } while (tokenizer.TokenType == ',');

        tokenizer.Advance();
    }

    return new GenericType(baseName, parameters);
}

