using System;
using System.Collections.Generic;

public class MainClass
{
    private Dictionary<int, string> mPendingFragmentActivityResults;
    private Dictionary<string, Fragment> mFragments;

    public void onRequestPermissionsResult(int requestCode, string[] permissions, int[] grantResults)
    {
        int index = (requestCode >> 16) & 0xffff;
        if (index != 0) {
            index--;
            string who = mPendingFragmentActivityResults[index];
            mPendingFragmentActivityResults.Remove(index);
            if (who == null) {
                Console.WriteLine("Activity result delivered for unknown fragment.");
                return;
            }
            if (!mFragments.TryGetValue(who, out Fragment frag)) {
                Console.WriteLine("Activity result no fragment exists for who: " + who);
            } else {
                frag.onRequestPermissionsResult(requestCode & 0xffff, permissions, grantResults);
            }
        }
    }
    public class Fragment {
        public void onRequestPermissionsResult(int requestCode, string[] permissions, int[] grantResults) {}
    }
}

