using System.Net.Sockets;

public void Run() {
    Console.WriteLine("New Communication Thread Started");
    try {
        using(NetworkStream stream = clientSocket.GetStream()) {
            using(StreamReader reader = new StreamReader(stream)) {
                using(StreamWriter writer = new StreamWriter(stream)) {
                    string inputLine;
                    while((inputLine = reader.ReadLine()) != null) {
                        Console.WriteLine("Received: " + inputLine);
                        if(long.TryParse(inputLine, out long pauseCommand)) {
                            writer.WriteLine("OK, pausing for " + inputLine + " ms");
                        }
                        if(inputLine.Equals("BYE")) {
                            writer.WriteLine("OK, bye!");
                            break;
                        }
                        if(inputLine.Equals("STOP")) {
                            writer.WriteLine("OK, stopping!");
                            Environment.Exit(1);
                        }
                    }
                }
            }
        }
    }
    catch(IOException) {
        Console.Error.WriteLine("Problem with Communication Server");
        Environment.Exit(1);
    }
}

