public ListNode SwitchPairs()
{
    if (this == null || this.next == null)
        return this;
    var top = this.next;
    var first = this;
    var second = first.next;
    do
    {
        var third = second.next;
        second.next = first;
        first.next = third;
        first = third;
        if (first != null)
        {
            second.next.next = first.next;
            second = first.next;
        }
    } while (first != null && second != null);
    return top;
}

