public class Program
{
    public static void Main()
    {
        LinkedList<string> list1 = new LinkedList<string>(new List<string>{"Cat", "Mouse", "Dog"});
        LinkedList<string> list2 = new LinkedList<string>(new List<string>{"Dog", "Mouse", "Cat"});
        LinkedList<string> list3 = new LinkedList<string>(new List<string>{"Dog", "Horse", "Cat"});
        LinkedList<string> list4 = new LinkedList<string>(new List<string>{"Dog", "Tiger", "Lion"});
