        foreach (var animals in list) {
            var arList = new List<string>(animals);
            arList.Sort();
            sorted.AddLast(new LinkedList<string>(arList));
        }

        foreach (var animals in sorted) {
            Console.WriteLine(string.Join(", ", animals));
        }
