public bool IsExpectedPassword(string password, byte[] salt, byte[] expectedHash)
{
    if (password == null)
        throw new ArgumentNullException("password");
    if (salt == null)
        throw new ArgumentNullException("salt");
    if (expectedHash == null)
        throw new ArgumentNullException("expectedHash");

    using (SHA512 sha512 = new SHA512Managed())
    {
        byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
        byte[] all = passwordBytes.Concat(salt).ToArray();
        byte[] hash = sha512.ComputeHash(all);

        return expectedHash.SequenceEqual(hash);
    }
}

