using System;

public class Program
{
    private static readonly Random random = new Random();
    private const string symbols = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    public static string GenerateRandomPassword(int length)
    {
        if (length < 1)
            throw new ArgumentException("length must be greater than 0");

        char[] buffer = new char[length];
        for (int i = 0; i < length; i++)
            buffer[i] = symbols[random.Next(symbols.Length)];

        return new string(Shuffle(buffer));
    }

    private static char[] Shuffle(char[] array)
    {
        for (int n = array.Length; n > 1;)
        {
            int k = random.Next(n--);
            var temp = array[n];
            array[n] = array[k];
            array[k] = temp;
        }
        return array;
    }
}

