using System;

public static bool IsBetween(int currentMonth, int currentDay, int fromMonth, int fromDay, int untilMonth, int untilDay) {
    DateTime current = new DateTime(1, currentMonth, currentDay);
    DateTime from = new DateTime(1, fromMonth, fromDay);
    DateTime until = new DateTime(1, untilMonth, untilDay);

    if (from <= until) {
        return from <= current && current <= until;
    } else {
        return current <= until || current >= from;
    }
}

