using System;
using System.Collections.Generic;

public class Program {
    public static void Main() {
        Console.WriteLine(decrypt("23#12"));
    }

    private static String decrypt (String s) {
        List<Int32> crypt = new List<Int32>();
        String[] groups = s.Split('#');
        for (int i = 0; i < groups.Length; i++) {
            String group = groups[i];
            int j = 0;
            if (i == groups.Length - 1 && !s.EndsWith("#")) {
                j = group.Length;
            }
            if (group.Length > 2) {
                j = group.Length - 2;
            }
            for (int k = 0; k < j; k++) {
                crypt.Add(Convert.ToInt32(group.Substring(k, 1)));
            }
            if (j < group.Length) {
                crypt.Add(Convert.ToInt32(group.Substring(j)));
            }
        }
        String n = "";
        foreach (Int32 c in crypt) {
            char d = (char) (('a' + c) - 1);
            n += d;
        }
        return n;
    }
}

