public int InterpolateColor(int a, int b, float proportion) {
    if(proportion > 1 || proportion < 0) {
        throw new ArgumentException("proportion must be [0 - 1]");
    }

    float[] hsva = ColorToHSV(a);
    float[] hsvb = ColorToHSV(b);
    float[] hsv_output = new float[3];
    for(int i = 0; i < 3; i++) {
        hsv_output[i] = Interpolate(hsva[i], hsvb[i], proportion);
    }
    int alpha_a = a >> 24;
    int alpha_b = b >> 24;
    int alpha_output = (int)Interpolate((float)alpha_a, (float)alpha_b, proportion);
    return HSVToColor(alpha_output, hsv_output);
}

