    float rand = (float) random.NextDouble();
    float highRange = Math.Max(numberOne, numberTwo);
    float lowRange = Math.Min(numberOne, numberTwo);
    float lowRand = (float) Math.Floor(rand - 1);
    float highRand = (float) Math.Ceiling(rand + 1);
