public static string Compress(string text) {
    string result = "";
    int index = 0;
    while (index < text.Length) {
        char c = text[index];
        int count = Count(text, c);
        if (count == 1) result += "" + c;
        else result += "" + count + c;
        index += count;
    }
    return result;
}

public static int Count(string text, char c) {
    int count = 0;
    for (int i = 0; i < text.Length; i++) {
        if (text[i] == c) {
            count++;
        }
    }
    return count;
}

