using System.Linq;

public static IComparable[] FindCommonElements (IComparable[][] collections) {
    var hashArray = collections.OrderBy(c => c.Length).First();
    var queryArray = collections.Except(new [] { hashArray }).SelectMany(c => c).ToArray();
    var intersectionSet = hashArray.Intersect(queryArray).ToArray();
    return intersectionSet;
}

