public int[] randNums(int total, int n) {
    int[] results = new int[n];
    Random rand = new Random();
    if (total == 0) {
        Array.Fill(results, 0);
        return results;
    }
    while (true) {
        var sum = 0L;
        for (int i = 0; i < n; i++) {
            results[i] = rand.Next();
            sum += results[i];
        }
        if (sum == 0) {
            continue;
        }
        for (int i = 0; i < n; i++) {
            results[i] = (int) ((results[i] + sum) % (total + 1));
        }
        return results;
    }
}

