public static int[] sort(int[] numbers, int digit)
{
    if (numbers.Length == 0 || digit <= 0) return numbers;
    var space = new List<int>[10];
    var len = new int[10];
    int i, j = 0;

    for (j = 0; j < numbers.Length; j++)
    {
        i = (numbers[j] / digit) % 10;
        if (space[i] == null)
            space[i] = new List<int>();
        len[i]++;
        space[i].Add(numbers[j]);
    }

    for (i = 0; i < 10; i++)
    {
        if (space[i] != null)
        {
            space[i] = sort(space[i].ToArray(), digit / 10).ToList();
        }
    }

    int k = 0;
    for (i = 0; i < 10; i++)
    {
        if (space[i] != null)
        {
            for (j = 0; j < len[i]; j++)
            {
                numbers[k] = space[i][j];
                k++;
            }
        }
    }
    return numbers;
}

