    int zeroesPos = 0, othersPos = nums.Length - 1;

    for(int i = 0; i < nums.Length; ++i) {
        if(nums[i] == 0) {
            result[zeroesPos++] = 0;
        } else {
            result[othersPos--] = nums[i];
        }
    }

    return result;
}

