public void Draw(Graphics2D g) {
    float arrowRatio = 0.5f;
    float arrowLength = 80.0f;
    Pen stroke = g.Pen;
    float endX = 350.0f;
    float veeX;

    if (stroke.LineJoin == LineJoin.Bevel) {
        veeX = endX - stroke.Width * 0.25f;
    } else if (stroke.LineJoin == LineJoin.MiterClipped || stroke.LineJoin == LineJoin.Miter) {
        veeX = endX - stroke.Width * 0.5f / arrowRatio;
    } else {
        veeX = endX - stroke.Width * 0.5f;
    }

    GraphicsPath path = new GraphicsPath();
    path.StartFigure();
    path.AddLine(veeX - arrowLength, -arrowRatio * arrowLength, veeX, 0.0f);
    path.AddLine(veeX, 0.0f, veeX - arrowLength, arrowRatio * arrowLength);
    path.CloseFigure();
    g.DrawPath(Pens.Blue, path);
    g.DrawLine(Pens.Yellow, 50.0f, 0.0f, veeX, 0.0f);
    g.DrawLine(Pens.Red, 50.0f, 0.0f, veeX - stroke.Width * 0.25f, 0.0f);
}

