using System.Collections;
using System.Linq;

public class Program {
    public static void Main() {
        var lc = new object[] {'A', 'B', 'C', 'D'};
        var lC = new object[] {'a', 'b', 'c'};
        var li = new object[] {1, 2, 3, 4};

        var llo = new[] {lc, lC, li};

        var tuples = llo.Skip(1).Aggregate(
            llo.First().Select( e => new Tuple<object, ArrayList>(e, new ArrayList())).ToArray(),
            (prev, next) => prev.SelectMany( t => next.Select( e => Tuple.Create(e, new ArrayList(t.Item2) {t.Item1}))).ToArray()
            );

        foreach (var t in tuples) {
            foreach (var element in t.Item2) {
                Console.Write(element + ", ");
            }
            Console.Write(t.Item1);
            Console.Write("\n");
        }
     }
}

