public int GetHashCode(IEnumerator enumerator)
{
    int hashCode = 1;

    while(enumerator.MoveNext())
    {
        object obj = enumerator.Current;
        hashCode = 31 * hashCode + (obj == null ? 0 : obj.GetHashCode());
    }

    return hashCode;
}

