private HashSet<object> visited = new HashSet<object>();
public string ToString(object obj)
{
    if (obj == null) return "null";
    if (visited.Contains(obj)) return "...";
    visited.Add(obj);
    Type cl = obj.GetType();
    if (cl == typeof(string)) return (string)obj;
    if (cl.IsArray)
    {
        string r = cl.GetElementType().Name + "[]{";
        Array array = (Array)obj;
        for (int i = 0; i < array.Length; i++)
        {
            if (i > 0) r += ",";
            object val = array.GetValue(i);
            if (cl.GetElementType().IsPrimitive) r += val.ToString();
            else r += ToString(val);
        }
        return r + "}";
    }
    string r = cl.Name;
    do {
        r += "[";
        FieldInfo[] fields = cl.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance);
        foreach (FieldInfo f in fields)
        {
            if (!r.EndsWith("[")) r += ",";
            r += f.Name + "=";
            try
            {
                Type t = f.FieldType;
                object val = f.GetValue(obj);
                if (t.IsPrimitive) r += val.ToString();
                else r += ToString(val);
            }
            catch (Exception e)
            {
                Console.Write(e);
            }
        }
        r += "]";
        cl = cl.BaseType;
    } while (cl != null);
    return r;
}

