public static string Join(string separator, params string[] values)
{
    if (values.Length == 0) return "";
    char[] sep = separator.ToCharArray();
    int totalSize = (values.Length - 1) * sep.Length;
    for (int i = 0; i < values.Length; i++)
    {
        if (values[i] == null) values[i] = "";
        else totalSize += values[i].Length;
    }
    List<char> joined = new List<char>(totalSize);
    int pos = 0;
    for (int i = 0, end = values.Length - 1; i < end; i++)
    {
        joined.AddRange(values[i].ToCharArray());
        pos += values[i].Length;
        joined.AddRange(sep);
        pos += sep.Length;
    }
    joined.AddRange(values[values.Length - 1].ToCharArray());
    return new string(joined.ToArray());
}

