using System;

public static class BitConverter
{
    private static char[] hexChars = "0123456789ABCDEF".ToCharArray();

    private static char NibbleToChar(byte b) {
        return hexChars[b & 0x0F];
    }

    public static string ToHexString(byte[] bytes)
    {
        if (bytes == null)
        {
            return null;
        }

        char[] result = new char[bytes.Length * 2];
        for (int iter = 0; iter < bytes.Length; ++iter)
        {
            result[2 * iter] = NibbleToChar((byte)(bytes[iter] >> 4));
            result[2 * iter + 1] = NibbleToChar(bytes[iter]);
        }

        return new string(result);
    }
}

