        if (points -- > 0) {
            int r = ran.nextInt (3);
            midPoint = midPoint.findMidTo (triangle [r]);
            gc.fillOval (midPoint.getX (), midPoint.getY (), 1, 1);
        } else {
            System.out.println ("Stopping!");
            timer.stop ();
        }
    }));
    timer.setCycleCount (Timeline.INDEFINITE);
    timer.play ();
}

