using System;

public static string GetDurationBreakdown(long millis)
{
    string[] units = { " Days ", " Hours ", " Minutes ", " Seconds " };
    long[] values = new long[units.Length];

    if (millis < 0) 
        throw new ArgumentException("Duration must be greater than zero!");

    values[0] = TimeSpan.FromMilliseconds(millis).Days;
    millis -= TimeSpan.FromDays(values[0]).TotalMilliseconds;

    values[1] = TimeSpan.FromMilliseconds(millis).Hours;
    millis -= TimeSpan.FromHours(values[1]).TotalMilliseconds;

    values[2] = TimeSpan.FromMilliseconds(millis).Minutes;
    millis -= TimeSpan.FromMinutes(values[2]).TotalMilliseconds;

    values[3] = TimeSpan.FromMilliseconds(millis).Seconds;

    var sb = new System.Text.StringBuilder(64);
    bool startPrinting = false;

    for (int i = 0; i < units.Length; i++)
    {
        if (!startPrinting && values[i] != 0) startPrinting = true;
        if (startPrinting)
        {
            sb.Append(values[i]);
            sb.Append(units[i]);
        }
    }

    return sb.ToString();
}

