using System;
using System.Threading;

public class Program
{
    private static Semaphore semaphore = new Semaphore(1, 1);
    private static int nextStartIdx = 0;

    public void print()
    {
        try
        {
            semaphore.WaitOne();

            int start = nextStartIdx;
            for (int i = 0; i < 5; i++)
            {
                Console.WriteLine(String.Format("{0} -- {1}", i + start, Thread.CurrentThread.Name));
            }
            nextStartIdx += 5;

            semaphore.Release();
        }
        catch (Exception)
        {
            Thread.CurrentThread.Interrupt();
        }
    }
}

