public static string Encrypt (string data) {
    string returned = "";
    foreach (char h in data) {
        switch (h) {
            case 'a': returned += " a', 'c"; break;
            case 'b': returned += "d"; break;
            /* other cases */
            case 'y': returned += "a"; break;
            case 'z': returned += "b"; break;
        }
    }
    return returned;
}

