public class FactorialProgram
{
    private static string Repeat(char c, int n) => new string(c, n);

    public static long Factorial(int n, int depth)
    {
        var spaces = Repeat(' ', depth);

        Console.WriteLine(spaces + "factorial(" + n + ")");

        if (n <= 1)
        {
            Console.WriteLine(spaces + " return 1");
            return 1;
        }

        var fac = Factorial(n - 1, depth + 1);

        Console.Write(spaces);
        Console.WriteLine($"return {n} * {fac} = {n * fac}");

        return n * fac;
    }
}

