    public static List<string> Tokenizer(string text, string[] delims)
    {
        for (int d = 0; d < delims.Length; d++)
        {
            string delim = delims[d];
            int i = text.IndexOf(delim);
            if(i>=0)
            {
                List<string> tail = Tokenizer(text.Substring(i + delim.Length), delims);
                List<string> list = new List<string> {text.Substring(0, i), delim};
                list.AddRange(tail);
                return list;
            }
        }
        return new List<string> { text };
    }
}

