static void merge(int[] a, int[] l, int[] r) {
    int totElem = l.Length + r.Length;
    int i, li, ri;
    i = li = ri = 0;
    while (i < totElem) {
        if ((li < l.Length) && (ri < r.Length)) {
            if (l [li] < r [ri]) {
                a [i] = l [li];
                i++;
                li++;
            } else {
                a [i] = r [ri];
                i++;
                ri++;
            }
        } else {
            if (li >= l.Length) {
                while (ri < r.Length) {
                    a [i] = r [ri];
                    i++;
                    ri++;
                }
            }
            if (ri >= r.Length) {
                while (li < l.Length) {
                    a [i] = l [li];
                    li++;
                    i++;
                }
            }
        }
    }
}

