public static byte[] Hash(string password, byte[] salt)
{
    if (password == null) throw new ArgumentNullException("password");
    if (salt == null) throw new ArgumentNullException("salt");
    var combinedBytes = new byte[password.Length + salt.Length];
    System.Buffer.BlockCopy(password.ToCharArray().Select(c => (byte)c).ToArray(), 0, combinedBytes, 0, password.Length);
    System.Buffer.BlockCopy(salt, 0, combinedBytes, password.Length, salt.Length);
    return new SHA512Managed().ComputeHash(combinedBytes);
}

