public static string Shuffle(string text) {
    char[] array = text.ToCharArray();
    Random rand = new Random();
    int n = array.Length;
    while (n > 1) {
        n--;
        int k = rand.Next(n + 1);
        var value = array[k];
        array[k] = array[n];
        array[n] = value;
    }
    return new string(array);
}

