static int Search(int [] A, int K) {
    int l = 0;
    int u = A.Length - 1;
    int m;
    while (l <= u) {
        m = (u + l) / 2;
        if (A[m] < K) l = m + 1;
        else if (A[m] == K) return m;
        else u = m - 1;
    }
    return -1;
}

