    {
        Console.WriteLine("Empty matrix");
        return;
    }
    Console.WriteLine(i + "," + j);
    var rightValue = i >= 0 && i + 1 < mat.GetLength(0) && mat[i, j] < mat[i+1, j] ? mat[i+1, j] : mat[i, j];
    var belowValue = j >= 0 && j + 1 < mat.GetLength(1) && mat[i, j] < mat[i, j+1] ? mat[i, j+1] : mat[i, j];
    var aboveValue = i > 0 && i - 1 < mat.GetLength(0) && mat[i, j] < mat[i-1, j] ? mat[i-1, j] : mat[i, j];
    var leftValue = j > 0 && j - 1 < mat.GetLength(1) && mat[i, j] < mat[i, j-1] ? mat[i, j-1] : mat[i, j];
    if (rightValue > leftValue)
    {
        if (rightValue > belowValue)
        {
            if (rightValue > aboveValue)
            {
                PrintPath(mat, i+1, j);
            }
            else
            {
                PrintPath(mat, i, j+1);
            }
        }
        else
        {
            if (belowValue > aboveValue)
            {
                PrintPath(mat, i-1, j);
            }
            else
            {
                PrintPath(mat, i, j+1);
            }
        }
    }
    else
    {
        if (leftValue > belowValue)
        {
            if (leftValue > aboveValue)
            {
                PrintPath(mat, i-1, j);
            }
            else
            {
                PrintPath(mat, i, j+1);
            }
        }
        else
        {
            if (belowValue > aboveValue)
            {
                PrintPath(mat, i-1, j);
            }
            else
            {
                PrintPath(mat, i, j+1);
            }
        }
    }
}

