public int Solution(int X, int[] A)
{
    var list = A;
    int sum = 0;
    var searchedValue = X;
    var sumV = searchedValue * (searchedValue + 1) / 2;
    var arrayList = new List<int>();
    for (int iii = 0; iii < list.Length; iii++)
    {
        if (list[iii] <= searchedValue && !arrayList.Contains(list[iii]))
        {
            sum += list[iii];
            if (sum == sumV)
