public String[][] AllUniqueCombinations()
{
    int n = dataStructure.Count;
    int solutions = 1;
    foreach (List<string> list in dataStructure.Values)
    {
        solutions *= list.Count;
    }

    String[][] allCombinations = new String[solutions + 1][];
    dataStructure.Keys.CopyTo(allCombinations[0], 0);

    for (int i = 0; i < solutions; i++)
    {
        List<string> combination = new List<string>(n);
        int j = 1;
        foreach(List<string> list in dataStructure.Values)
        {
            combination.Add(list[(i / j) % list.Count]);
            j *= list.Count;
        }

        combination.ToArray().CopyTo(allCombinations[i + 1], 0);
    }

    return allCombinations;
}

