public static string Merge(params string[] strings) {
    int maxLength = 0;
    StringBuilder sb = new StringBuilder();
    foreach (string s in strings) 
        if (s.Length > maxLength) 
            maxLength = s.Length;

    for (int i = 0; i < maxLength; i++) 
        foreach (string s in strings) 
            if (s.Length > i) 
                sb.Append(s[i]);

    return sb.ToString();
}

