public BSTNode MirrorView(BSTNode node) 
{
    if (node == null || (node.Left == null && node.Right == null)) return node;
    BSTNode temp = node.Left;
    node.Left = node.Right;
    node.Right = temp;
    MirrorView(node.Left);
    MirrorView(node.Right);
    return node;
}

